      "code": "\"\"\"Independent SASA review: local NumPy, no execution of supplied source.\"\"\"\nimport collections, hashlib, importlib.metadata, json, math, platform\nfrom pathlib import Path\nimport numpy as np\nfrom jsonschema import Draft7Validator\nraw = {p.name:p.read_bytes() for p in sorted(Path('inputs').iterdir()) if p.is_file()}\nassert set(raw)=={'context.json','source-1CRN.pdb','sasa.json'}\nc=json.loads(raw['context.json']); env=json.loads(raw['sasa.json']); s=env['result']\nreceipts=[dict(filename=k,sha256=hashlib.sha256(v).hexdigest(),size=len(v)) for k,v in raw.items()]\nrm={r['filename']:r for r in receipts}\natoms=[]; coord=[]\nfor line in raw['source-1CRN.pdb'].decode('ascii').splitlines():\n    if line[:6] in ('ATOM  ','HETATM'): coord.append(line)\n    if line[:6]!='ATOM  ' or line[21]!='A' or line[16] not in (' ','A'): continue\n    el=line[76:78].strip().upper()\n    if el in ('H','D'): continue\n    assert el in ('C','N','O','S')\n    atoms.append(dict(serial=int(line[6:11]),atom_name=line[12:16].strip(),chain=line[21],residue_id=int(line[22:26]),insertion_code=line[26].strip(),residue_name=line[17:20],element=el,xyz_A=[float(line[a:b]) for a,b in ((30,38),(38,46),(46,54))]))\nkeys=[(a['chain'],a['residue_id'],a['insertion_code']) for a in atoms]\nassert len(set((keys[i],a['atom_name']) for i,a in enumerate(atoms)))==len(atoms)\nassert all(not a['insertion_code'] for a in atoms)\nassert len(atoms)==s['atom_count']==327 and len(set(keys))==s['residue_count']==46\nassert s['source_sha256']==rm['source-1CRN.pdb']['sha256']\nassert next(r for r in env['inputReceipts'] if r['filename']=='source-1CRN.pdb')==rm['source-1CRN.pdb']\n# Independently implemented double-precision Fibonacci sphere and point occlusion.\nn=5000; probe=1.4; radii={'C':1.70,'N':1.55,'O':1.52,'S':1.80}\nk=np.arange(n,dtype=float); z=1-2*(k+0.5)/n\nphi=k*(math.pi*(3-math.sqrt(5)))+0.618; rho=np.sqrt(1-z*z)\nsphere=np.column_stack((rho*np.cos(phi),rho*np.sin(phi),z))\nxyz=np.array([a['xyz_A'] for a in atoms]); r=np.array([radii[a['element']]+probe for a in atoms])\nra=collections.defaultdict(float)\nfor i,a in enumerate(atoms):\n    d2=np.sum((xyz-xyz[i])**2,axis=1)\n    neighbors=np.flatnonzero((d2<(r+r[i])**2)&(np.arange(len(atoms))!=i))\n    points=xyz[i]+r[i]*sphere; exposed=np.ones(n,dtype=bool)\n    for j in neighbors:\n        active=np.flatnonzero(exposed)\n        if not len(active): break\n        pd2=np.sum((points[active]-xyz[j])**2,axis=1)\n        exposed[active[pd2<r[j]**2]]=False\n    a['exposed_points']=int(exposed.sum())\n    a['area_A2']=4*math.pi*r[i]**2*a['exposed_points']/n\n    ra[a['residue_id']]+=a['area_A2']\nbaseline=math.fsum(a['area_A2'] for a in atoms); rows=s['residues']\nassert [x['residue_id'] for x in rows]==list(range(1,47))\nassert all(type(x['area_A2']) in (int,float) and math.isfinite(x['area_A2']) and x['area_A2']>=0 for x in rows)\nrs=math.fsum(x['area_A2'] for x in rows); pct=abs(s['total_A2']-baseline)/baseline*100\nschema_errors=[e.message for e in Draft7Validator(c['resultSchemas']['sasa']).iter_errors(s)]\nchecks=[]\nfor rule in c['scientificChecks']['tasks']['sasa']:\n    if rule['kind']=='sum':\n        observed=math.fsum(x[rule['valueField']] for x in s[rule['rowsPath']]); expected=s[rule['totalPath']]\n    else: observed=s[rule['path']]; expected=rule['expected']\n    tol=rule['absoluteTolerance']+rule.get('relativeTolerance',0)*abs(expected)\n    checks.append(dict(id=rule['id'],observed=observed,expected=expected,absolute_difference=abs(observed-expected),tolerance=tol,passed=abs(observed-expected)<=tol))\n# Inspect/hash original source as data only. A blank line precedes the Markdown fence.\nf=c['feedback']; fenced=f.split('```python\\n',1)[1].split('```',1)[0]\noriginal=fenced[:-1] if fenced.endswith('\\n\\n') else fenced\nosh=hashlib.sha256(original.encode()).hexdigest()\nassert len(original.encode())==4065 and osh=='cb9f13f43624bb851b6f24e6e3600f00c73e84a24c068430afc906bf04c050e1'\na