          "code": "#!/usr/bin/env python3\n\"\"\"\nExecute Bio.PDB.SASA.ShrakeRupley on the frozen 1CRN structure.\nSelection: chain A, ATOM heavy atoms, altloc blank/A. Exclude HETATM and hydrogens.\nParameters: n_points=1000, probe_radius=1.4, radii C=1.70,N=1.55,O=1.52,S=1.80.\n\"\"\"\nimport hashlib\nimport json\nfrom Bio.PDB import PDBParser\nfrom Bio.PDB.SASA import ShrakeRupley\n\nSOURCE = \"source-1CRN.pdb\"\n\n# --- Verify source SHA256 ---\nwith open(SOURCE, \"rb\") as f:\n    raw = f.read()\nsource_sha256 = hashlib.sha256(raw).hexdigest()\nprint(\"source_sha256:\", source_sha256)\nprint(\"source size bytes:\", len(raw))\n\n# --- Parse structure ---\nparser = PDBParser(QUIET=True)\nstructure = parser.get_structure(\"1CRN\", SOURCE)\n\n# Select chain A\nmodel = structure[0]\nchain = model[\"A\"]\n\n# --- Count atoms/residues under frozen selection ---\n# ATOM heavy atoms, chain A, altloc blank/A, exclude HETATM and hydrogens\natom_count = 0\nresidue_ids = []\nfor residue in chain:\n    if residue.id[0] != \" \":  # exclude hetero residues (HETATM)\n        continue\n    res_atoms = []\n    for atom in residue:\n        # altloc blank/A\n        altloc = atom.get_altloc()\n        if altloc not in (\" \", \"A\"):\n            continue\n        # exclude hydrogens\n        element = atom.element.strip().upper()\n        if element in (\"H\", \"D\"):\n            continue\n        res_atoms.append(atom)\n    if res_atoms:\n        residue_ids.append(residue.id[1])\n        atom_count += len(res_atoms)\n\nprint(\"atom_count:\", atom_count)\nprint(\"residue_count:\", len(residue_ids))\nprint(\"residue_ids:\", residue_ids)\n\n# --- Run ShrakeRupley ---\nsr = ShrakeRupley(probe_radius=1.4, n_points=1000)\n# Element radii: C=1.70, N=1.55, O=1.52, S=1.80\nsr.radii_dict = {\"C\": 1.70, \"N\": 1.55, \"O\": 1.52, \"S\": 1.80}\nsr.compute(chain, level=\"R\")\n\n# --- Collect per-residue areas ---\nresidues_out = []\ntotal = 0.0\nfor residue in chain:\n    if residue.id[0] != \" \":\n        continue\n    area = residue.sasa\n    residues_out.append({\"residue_id\": residue.id[1], \"area_A2\": round(area, 4)})\n    total += area\n\nprint(\"total_A2:\", total)\nprint(\"sum of residue areas:\", sum(r[\"area_A2\"] for r in residues_out))\n\n# --- Write sasa.json envelope ---\nresult = {\n    \"method\": \"Shrake-Rupley\",\n    \"probe_radius_A\": 1.4,\n    \"n_points\": 1000,\n    \"atom_count\": atom_count,\n    \"residue_count\": len(residue_ids),\n    \"source_sha256\": source_sha256,\n    \"total_A2\": round(total, 4),\n    \"residues\": residues_out,\n    \"interpretation\": (\n        \"Solvent-accessible surface area (SASA) of the single frozen 1CRN structure \"\n        \"(chain A, 46 residues, 327 heavy atoms) computed with the Shrake-Rupley \"\n        \"geometric method using n_points=1000, probe_radius=1.4 Angstrom, and element \"\n        \"radii C=1.70, N=1.55, O=1.52, S=1.80 Angstrom. This is a reproducibility \"\n        \"exercise for one fixed structure, not a biological discovery. Values are in \"\n        \"square Angstrom (A^2).\"\n    ),\n    \"limitations\": (\n        \"SASA is a geometric measure dependent on the chosen probe radius, point \"\n        \"density (n_points), and element radii. Results apply only to this fixed \"\n        \"structure and this geometric method; no biological function ranking or \"\n        \"causal claims are made. The Shrake-Rupley method approximates the surface \"\n        \"by sampling a finite number of points per atom, so results are approximate \"\n        \"and may differ slightly from other SASA implementations.\"\n    ),\n}\n\nenvelope = {\n    \"revision\": 1,\n    \"inputReceipts\": [\n        {\n            \"filename\": \"context.json\",\n            \"sha256\": hashlib.sha256(open(\"context.json\", \"rb\").read()).hexdigest(),\n            \"size\": len(open(\"context.json\", \"rb\").read()),\n        },\n        {\n            \"filename\": \"source-1CRN.pdb\",\n            \"sha256\": source_sha256,\n            \"size\": len(raw),\n        },\n    ],\n    \"result\": result,\n}\n\nwith open(\"sasa.json\", \"w\") as f:\n    json.dump(envelope, f, indent=2)\n\nprint(\"\\nWrote sasa.json\")\nprint(\"inputReceipts:\")\nfor r in envelope[\"inputReceipts\"]:\n    print(\" \", r[\"filename\"], r[\"sha256\"], r[\"size\"])\n",
